<div class="d-flex justify-content-end mb-3"><?php if (in_array('package.create', $perms)): ?><a class="btn btn-primary" href="<?= site_url('partner/packages/form') ?>"><i class="bi bi-plus-lg"></i> Tambah Paket</a><?php endif; ?></div>
<div class="card p-3"><table class="table table-hover dt"><thead><tr><th></th><th>Paket</th><th>Kategori</th><th>Harga mulai</th><th>Jadwal buka</th><th>Persetujuan</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?php if ($r->cover_path): ?><img src="<?= e(media_url($r->cover_path)) ?>" style="width:56px;height:40px;object-fit:cover;border-radius:6px"><?php endif; ?></td><td><?= e($r->name) ?><?php if ($r->approval_note): ?><br><small class="text-danger"><?= e($r->approval_note) ?></small><?php endif; ?></td><td><?= e($r->category_name) ?></td><td><?= rupiah($r->base_price) ?></td><td><?= (int)$r->open_sched ?></td><td><?= badge($r->approval_status) ?></td><td><?= badge($r->status) ?></td>
<td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('partner/packages/form/' . $r->id) ?>">Ubah</a> <a class="btn btn-sm btn-outline-info" href="<?= site_url('partner/schedules/index/' . $r->id) ?>">Jadwal</a>
<?php if (in_array($r->approval_status, ['draft', 'rejected'])): ?><?= post_btn('partner/packages/submit/' . $r->id, 'Ajukan', 'btn-success', [], 'Ajukan paket ke platform?') ?>
<?php elseif ($r->approval_status === 'approved'): ?><?= post_btn('partner/packages/toggle/' . $r->id, $r->status === 'active' ? 'Nonaktifkan' : 'Aktifkan', 'btn-outline-secondary') ?><?php endif; ?>
<?= in_array('package.delete', $perms) ? post_btn('partner/packages/remove/' . $r->id, 'Hapus', 'btn-outline-danger', [], 'Hapus paket?') : '' ?></td></tr><?php endforeach; ?></tbody></table></div>
